declare
    plan_status text;

    old_business_state jsonb;
    new_business_state jsonb;
begin

    if tg_op = 'DELETE' then

        plan_status :=
            public.get_daily_plan_status(
                old.workspace_id,
                old.daily_plan_id
            );


        if plan_status <> 'draft' then
            raise exception
                'Daily Plan Items may only be deleted while the Plan is a draft';
        end if;


        return old;

    end if;


    plan_status :=
        public.get_daily_plan_status(
            new.workspace_id,
            new.daily_plan_id
        );


    if plan_status is null then
        raise exception
            'Daily Plan does not exist';
    end if;


    -- --------------------------------------------------------
    -- INSERT
    -- --------------------------------------------------------

    if tg_op = 'INSERT' then

        if plan_status <> 'draft' then
            raise exception
                'Daily Plan Items may only be added to draft Plans';
        end if;


        new.completion_status := 'pending';

        return new;

    end if;


    -- --------------------------------------------------------
    -- Historical Plan
    -- --------------------------------------------------------

    if plan_status in (
        'completed',
        'superseded'
    ) then

        raise exception
            'Daily Plan Items on historical Plans are immutable';

    end if;


    -- --------------------------------------------------------
    -- Draft Plan
    -- --------------------------------------------------------

    if plan_status = 'draft' then

        new.completion_status := 'pending';

        return new;

    end if;


    -- --------------------------------------------------------
    -- Active Plan
    --
    -- Only completion_status may change.
    -- --------------------------------------------------------

    if plan_status = 'active' then

        old_business_state :=
            to_jsonb(old)
            - array[
                'completion_status',
                'updated_at',
                'updated_by_principal_id'
            ];


        new_business_state :=
            to_jsonb(new)
            - array[
                'completion_status',
                'updated_at',
                'updated_by_principal_id'
            ];


        if old_business_state
           is distinct from new_business_state then

            raise exception
                'Active Daily Plan Item structure is frozen';

        end if;


        -- Once the day records an outcome for this item, that
        -- historical outcome is terminal.

        if old.completion_status in (
            'completed',
            'carried_forward',
            'removed'
        )
        and new.completion_status
            is distinct from old.completion_status then

            raise exception
                'Finalized Daily Plan Item outcomes are immutable';

        end if;


        if old.completion_status = 'pending'
           and new.completion_status not in (
               'pending',
               'completed',
               'carried_forward',
               'removed'
           ) then

            raise exception
                'Invalid Daily Plan Item completion transition';

        end if;


        return new;

    end if;


    return new;

end;

declare candidate uuid; action public.next_actions%rowtype;
begin
  candidate:=private.hq_workspace_candidate(w);
  if not public.has_permission(w,'next_action.read') then
    raise exception using errcode='42501',message='Next Action read authority required';
  end if;
  select * into action from public.next_actions where workspace_id=w and id=a for share;
  if not found or action.status<>'open'
     or (action.assigned_to_principal_id is not null and action.assigned_to_principal_id<>candidate)
     or (action.available_after is not null and
       (not isfinite(action.available_after) or action.available_after>clock_timestamp())) then
    raise exception using errcode='40001',message='Next Action is not currently candidate-eligible';
  end if;
end;

declare a uuid;
begin
  -- Later deferral does not rewrite history or prohibit completion. Existing
  -- lifecycle guards still enforce historical immutability/completion rules.
  if new.status in ('completed','superseded') then return new; end if;
  if tg_op='UPDATE' and new.todays_one_thing_action_id is not distinct from old.todays_one_thing_action_id
     and not(old.status='draft' and new.status='active') then return new; end if;
  if new.todays_one_thing_action_id is not null then
    perform private.hq_assert_action_eligible(new.workspace_id,new.todays_one_thing_action_id);
  end if;
  if tg_op='UPDATE' and old.status='draft' and new.status='active' then
    for a in select i.next_action_id from public.daily_plan_items i
      where i.workspace_id=new.workspace_id and i.daily_plan_id=new.id order by i.next_action_id loop
      perform private.hq_assert_action_eligible(new.workspace_id,a);
    end loop;
  end if;
  return new;
end;
